script:
frappe.ui.form.on('Item', {
    refresh: function(frm) {

        // Check only saved Items
        if (frm.is_new() || !frm.doc.item_code) {
            return;
        }

        const minimum_stock = flt(
            frm.doc.custom_minimum_stock_level || 10
        );

        frappe.db.get_list('Bin', {
            filters: {
                item_code: frm.doc.item_code
            },
            fields: [
                'warehouse',
                'actual_qty'
            ],
            limit: 1000
        }).then(records => {

            // Calculate total stock across warehouses
            let actual_stock = records.reduce(
                (total, row) => total + flt(row.actual_qty),
                0
            );

            // Prepare warehouse-wise stock details
            let warehouse_details = records.map(row => `
                <tr>
                    <td>${frappe.utils.escape_html(row.warehouse)}</td>
                    <td>${flt(row.actual_qty)}</td>
                </tr>
            `).join('');

            // Check minimum stock level
            if (actual_stock < minimum_stock) {

                frappe.msgprint({
                    title: __('Low Stock Warning'),
                    indicator: 'red',
                    message: `
                        <b>Item:</b>
                        ${frappe.utils.escape_html(frm.doc.item_name)}
                        <br>

                        <b>Minimum Stock Level:</b>
                        ${minimum_stock}
                        <br>

                        <b>Available Stock:</b>
                        ${actual_stock}
                        <br><br>

                        <b>Warning:</b>
                        Stock is below the minimum required level.

                        <hr>

                        <b>Warehouse-wise Stock:</b>

                        <table class="table table-bordered">
                            <thead>
                                <tr>
                                    <th>Warehouse</th>
                                    <th>Actual Qty</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${warehouse_details}
                            </tbody>
                        </table>
                    `
                });

            } else {

                frappe.msgprint({
                    title: __('Stock Available'),
                    indicator: 'green',
                    message: `
                        <b>Item:</b>
                        ${frappe.utils.escape_html(frm.doc.item_name)}
                        <br>

                        <b>Minimum Stock Level:</b>
                        ${minimum_stock}
                        <br>

                        <b>Available Stock:</b>
                        ${actual_stock}
                        <br><br>

                        Stock is sufficient.
                    `
                });
            }

        }).catch(error => {
            console.error('Stock Fetch Error:', error);

            frappe.msgprint({
                title: __('Stock Check Failed'),
                indicator: 'red',
                message: __('Unable to fetch stock details.')
            });
        });
    }
});
